"""Error hierarchy shared by every tallybook module."""


class TallybookError(Exception):
    """Base class of every error caused by what was asked for."""

    code = "error"

    def __init__(self, message="", **detail):
        super().__init__(message)
        self.message = str(message)
        self.detail = dict(detail) if detail else {}

    def __str__(self):
        return self.message


class ParseError(TallybookError):
    code = "parse"


class ValidationError(TallybookError):
    code = "validation"


class NotFoundError(TallybookError):
    code = "not_found"


class ConflictError(TallybookError):
    code = "conflict"


def is_int(value):
    """True for a real integer (never a bool)."""
    return isinstance(value, int) and not isinstance(value, bool)
"""Exact money: whole minor units and a currency code."""

import re

from tallybook.currency import CurrencyError, currency
from tallybook.errors import ValidationError, is_int

__all__ = ["Money", "MoneyError", "parse_amount", "format_minor", "round_div"]


class MoneyError(ValidationError):
    """A bad amount or an operation mixing currencies."""


def round_div(n, d):
    """n / d rounded to the nearest integer, halves away from zero."""
    if not is_int(n) or not is_int(d):
        raise MoneyError("round_div needs integers, got %r and %r" % (n, d))
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, got %r" % (d,))
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


def format_minor(minor, code):
    exp = currency(code).exponent
    if not is_int(minor):
        raise MoneyError("minor units must be an integer, got %r" % (minor,))
    sign = "-" if minor < 0 else ""
    digits = str(abs(minor))
    if exp == 0:
        return sign + digits
    digits = digits.rjust(exp + 1, "0")
    return sign + digits[:-exp] + "." + digits[-exp:]


_AMOUNT_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def parse_amount(text, code):
    exp = currency(code).exponent
    if not isinstance(text, str):
        raise MoneyError("invalid amount %r: expected text" % (text,))
    m = _AMOUNT_RE.fullmatch(text)
    if not m:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.groups()
    if frac is not None:
        if exp == 0:
            raise MoneyError("invalid amount '%s': %s has no decimals" % (text, code))
        if len(frac) > exp:
            raise MoneyError("invalid amount '%s': %s has at most %d decimals" % (text, code, exp))
    frac = (frac or "").ljust(exp, "0")
    value = int(whole) * 10 ** exp + (int(frac) if frac else 0)
    return -value if sign == "-" else value


class Money:
    __slots__ = ("_minor", "_currency")

    def __init__(self, minor, currency_code):
        if not is_int(minor):
            raise MoneyError("minor units must be an integer, got %r" % (minor,))
        currency(currency_code)
        object.__setattr__(self, "_minor", int(minor))
        object.__setattr__(self, "_currency", currency_code)

    @property
    def minor(self):
        return self._minor

    @property
    def currency(self):
        return self._currency

    @property
    def exponent(self):
        return currency(self._currency).exponent

    def __setattr__(self, name, value):
        raise AttributeError("Money is immutable")

    def __delattr__(self, name):
        raise AttributeError("Money is immutable")

    def __reduce__(self):
        return (Money, (self._minor, self._currency))

    def __copy__(self):
        return self

    def __deepcopy__(self, memo):
        return self

    @classmethod
    def zero(cls, code):
        return cls(0, code)

    @classmethod
    def of(cls, text, code):
        return cls(parse_amount(text, code), code)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise MoneyError("invalid money %r: expected text" % (text,))
        parts = text.split(" ")
        if len(parts) != 2 or not parts[0] or not parts[1] or any(c in text for c in "\t\r\n\v\f"):
            raise MoneyError("invalid money '%s': expected 'AMOUNT CUR'" % (text,))
        amount, code = parts
        currency(code)
        return cls(parse_amount(amount, code), code)

    def amount_str(self):
        return format_minor(self._minor, self._currency)

    def __str__(self):
        return "%s %s" % (self.amount_str(), self._currency)

    def __repr__(self):
        return "Money(%d, '%s')" % (self._minor, self._currency)

    def __hash__(self):
        return hash((self._minor, self._currency))

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self._minor == other._minor and self._currency == other._currency

    def __ne__(self, other):
        return not self.__eq__(other)

    def _same(self, other, verb):
        if not isinstance(other, Money):
            return False
        if other._currency != self._currency:
            raise MoneyError("cannot %s %s and %s: different currencies" % (verb, self._currency, other._currency))
        return True

    def __add__(self, other):
        if not self._same(other, "add"):
            return NotImplemented
        return Money(self._minor + other._minor, self._currency)

    def __sub__(self, other):
        if not self._same(other, "subtract"):
            return NotImplemented
        return Money(self._minor - other._minor, self._currency)

    def __neg__(self):
        return Money(-self._minor, self._currency)

    def __pos__(self):
        return self

    def __abs__(self):
        return Money(abs(self._minor), self._currency)

    def __mul__(self, other):
        if not is_int(other):
            return NotImplemented
        return Money(self._minor * other, self._currency)

    __rmul__ = __mul__

    def __lt__(self, other):
        if not self._same(other, "compare"):
            return NotImplemented
        return self._minor < other._minor

    def __le__(self, other):
        if not self._same(other, "compare"):
            return NotImplemented
        return self._minor <= other._minor

    def __gt__(self, other):
        if not self._same(other, "compare"):
            return NotImplemented
        return self._minor > other._minor

    def __ge__(self, other):
        if not self._same(other, "compare"):
            return NotImplemented
        return self._minor >= other._minor

    def is_zero(self):
        return self._minor == 0

    def sign(self):
        return (self._minor > 0) - (self._minor < 0)

    def scale(self, num, den=1):
        if not is_int(num) or not is_int(den):
            raise MoneyError("scale needs integers, got %r and %r" % (num, den))
        if den == 0:
            raise MoneyError("scale by a ratio with a zero denominator")
        if den < 0:
            num, den = -num, -den
        return Money(round_div(self._minor * num, den), self._currency)

    def allocate(self, weights):
        if not isinstance(weights, (list, tuple)) or not weights:
            raise MoneyError("allocate needs a non-empty list of weights")
        for w in weights:
            if not is_int(w) or w < 0:
                raise MoneyError("invalid weight %r: weights are whole numbers of at least 0" % (w,))
        total = sum(weights)
        if total <= 0:
            raise MoneyError("allocate needs weights with a positive sum")
        amount = abs(self._minor)
        parts = [amount * w // total for w in weights]
        rems = [amount * w % total for w in weights]
        left = amount - sum(parts)
        order = sorted(range(len(weights)), key=lambda i: (-rems[i], i))
        for i in order[:left]:
            parts[i] += 1
        neg = self._minor < 0
        return [Money(-p if neg else p, self._currency) for p in parts]
"""Currencies and exchange rates."""

import bisect
import datetime
import re
from dataclasses import dataclass
from fractions import Fraction

from tallybook.errors import ValidationError


class CurrencyError(ValidationError):
    """An unknown currency, a bad rate or a missing rate."""


@dataclass(frozen=True)
class Currency:
    code: str
    exponent: int
    name: str
    symbol: str


CURRENCIES = {
    c.code: c
    for c in [
        Currency("USD", 2, "US Dollar", "$"),
        Currency("EUR", 2, "Euro", "€"),
        Currency("GBP", 2, "British Pound", "£"),
        Currency("JPY", 0, "Japanese Yen", "¥"),
        Currency("CHF", 2, "Swiss Franc", "CHF"),
        Currency("CAD", 2, "Canadian Dollar", "CA$"),
        Currency("AUD", 2, "Australian Dollar", "A$"),
        Currency("KWD", 3, "Kuwaiti Dinar", "KD"),
        Currency("SEK", 2, "Swedish Krona", "kr"),
        Currency("INR", 2, "Indian Rupee", "₹"),
        Currency("NZD", 2, "New Zealand Dollar", "NZ$"),
        Currency("NOK", 2, "Norwegian Krone", "kr"),
        Currency("KRW", 0, "South Korean Won", "₩"),
        Currency("BHD", 3, "Bahraini Dinar", "BD"),
        Currency("CNY", 2, "Chinese Yuan", "CN¥"),
        Currency("MXN", 2, "Mexican Peso", "MX$"),
    ]
}


def currency(code):
    """The Currency for a code; CurrencyError when unknown."""
    if isinstance(code, str) and code in CURRENCIES:
        return CURRENCIES[code]
    raise CurrencyError("unknown currency %r" % (code,))


def is_currency(code):
    return isinstance(code, str) and code in CURRENCIES


_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")


def parse_rate_text(text):
    """Read a rate text into a positive Fraction (CurrencyError otherwise)."""
    if not isinstance(text, str) or not _RATE_RE.fullmatch(text):
        raise CurrencyError("invalid rate %s: expected a positive decimal number"
                            % ("'%s'" % text if isinstance(text, str) else repr(text)))
    value = Fraction(text)
    if value <= 0:
        raise CurrencyError("invalid rate '%s': must be positive" % (text,))
    return value


def _check_date(on):
    if not isinstance(on, datetime.date) or isinstance(on, datetime.datetime):
        raise CurrencyError("invalid date %r: expected a date" % (on,))


class RateTable:
    """Exchange rates by direction and day."""

    def __init__(self):
        # (src, dst) -> sorted list of dates, and dict date -> Fraction
        self._dates = {}
        self._rates = {}

    def set(self, src, dst, rate_text, on):
        currency(src)
        currency(dst)
        if src == dst:
            raise CurrencyError("cannot set a rate from %s to itself" % src)
        value = parse_rate_text(rate_text)
        _check_date(on)
        key = (src, dst)
        dates = self._dates.setdefault(key, [])
        rates = self._rates.setdefault(key, {})
        if on not in rates:
            bisect.insort(dates, on)
        rates[on] = value

    def _latest(self, src, dst, on):
        dates = self._dates.get((src, dst))
        if not dates:
            return None
        i = bisect.bisect_right(dates, on)
        if i == 0:
            return None
        return self._rates[(src, dst)][dates[i - 1]]

    def rate(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        if src == dst:
            return Fraction(1)
        direct = self._latest(src, dst, on)
        if direct is not None:
            return direct
        inverse = self._latest(dst, src, on)
        if inverse is not None:
            return 1 / inverse
        raise CurrencyError("no rate %s -> %s on %s" % (src, dst, on.isoformat()))

    def convert(self, money, dst, on):
        from tallybook.money import Money, round_div

        if not isinstance(money, Money):
            raise CurrencyError("cannot convert %r: not a Money" % (money,))
        target = currency(dst)
        _check_date(on)
        if money.currency == dst:
            return money
        r = self.rate(money.currency, dst, on)
        shift = target.exponent - currency(money.currency).exponent
        num = money.minor * r.numerator
        den = r.denominator
        if shift >= 0:
            num *= 10 ** shift
        else:
            den *= 10 ** (-shift)
        return Money(round_div(num, den), dst)

    def entries(self):
        out = []
        for (src, dst) in sorted(self._dates):
            for d in self._dates[(src, dst)]:
                out.append((src, dst, d, self._rates[(src, dst)][d]))
        return out

    def remove(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        rates = self._rates.get((src, dst))
        if not rates or on not in rates:
            raise CurrencyError("no rate %s -> %s set on %04d-%02d-%02d" % (src, dst, on.year, on.month, on.day))
        del rates[on]
        self._dates[(src, dst)].remove(on)
        if not rates:
            del self._rates[(src, dst)]
            del self._dates[(src, dst)]

    def copy(self):
        t = RateTable()
        for src, dst, d, r in self.entries():
            t._dates.setdefault((src, dst), []).append(d)
            t._rates.setdefault((src, dst), {})[d] = r
        return t
"""Strict dates, month arithmetic and periods."""

import datetime
import re

from tallybook.errors import ParseError, is_int

__all__ = ["parse_date", "format_date", "add_months", "last_day", "Period", "periods", "DateError"]


class DateError(ParseError):
    """A malformed date, period or date computation out of range."""


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def _is_date(value):
    return isinstance(value, datetime.date) and not isinstance(value, datetime.datetime)


def _q(text):
    return "'%s'" % text if isinstance(text, str) else repr(text)


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date %s: expected YYYY-MM-DD text" % _q(text))
    m = _DATE_RE.fullmatch(text)
    if not m:
        raise DateError("invalid date %s: expected YYYY-MM-DD" % _q(text))
    y, mo, d = (int(g) for g in m.groups())
    try:
        return datetime.date(y, mo, d)
    except ValueError:
        raise DateError("invalid date %s: no such day" % _q(text)) from None


def format_date(d):
    if not _is_date(d):
        raise DateError("not a date: %r" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not is_int(year) or not is_int(month):
        raise DateError("year and month must be integers, got %r and %r" % (year, month))
    if not 1 <= month <= 12:
        raise DateError("invalid month %r" % (month,))
    if not 1 <= year <= 9999:
        raise DateError("invalid year %r" % (year,))
    if month == 12:
        return 31
    return (datetime.date(year, month + 1, 1) - datetime.timedelta(days=1)).day


def add_months(d, n):
    if not _is_date(d):
        raise DateError("not a date: %r" % (d,))
    if not is_int(n):
        raise DateError("number of months must be an integer, got %r" % (n,))
    total = d.year * 12 + (d.month - 1) + n
    y, m = divmod(total, 12)
    m += 1
    if not 1 <= y <= 9999:
        raise DateError("date out of range: %s moved by %d months" % (format_date(d), n))
    return datetime.date(y, m, min(d.day, last_day(y, m)))


_QUARTER_START = {1: 1, 2: 4, 3: 7, 4: 10}


class Period:
    __slots__ = ("_start", "_end")

    def __init__(self, start, end):
        if not _is_date(start) or not _is_date(end):
            raise DateError("a period needs two dates, got %r and %r" % (start, end))
        if end < start:
            raise DateError("empty period: %s is before %s" % (format_date(end), format_date(start)))
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_end", end)

    @property
    def start(self):
        return self._start

    @property
    def end(self):
        return self._end

    def __setattr__(self, name, value):
        raise AttributeError("Period is immutable")

    def __reduce__(self):
        return (Period, (self._start, self._end))

    def __eq__(self, other):
        return isinstance(other, Period) and self._start == other._start and self._end == other._end

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self._start, self._end))

    def __repr__(self):
        return "Period(%r, %r)" % (self._start, self._end)

    def contains(self, d):
        if not _is_date(d):
            raise DateError("not a date: %r" % (d,))
        return self._start <= d <= self._end

    def __contains__(self, d):
        return self.contains(d)

    @property
    def days(self):
        return (self._end - self._start).days + 1

    def _kind(self):
        s, e = self._start, self._end
        if s.day == 1 and e.day == last_day(e.year, e.month) and s.year == e.year:
            if s.month == 1 and e.month == 12:
                return "year"
            if s.month == e.month:
                return "month"
            if s.month in (1, 4, 7, 10) and e.month == s.month + 2:
                return "quarter"
        return "range"

    @property
    def label(self):
        kind = self._kind()
        s = self._start
        if kind == "year":
            return "%04d" % s.year
        if kind == "month":
            return "%04d-%02d" % (s.year, s.month)
        if kind == "quarter":
            return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
        return "%s..%s" % (format_date(self._start), format_date(self._end))

    def __str__(self):
        return self.label

    def next(self):
        kind = self._kind()
        try:
            if kind == "range":
                start = self._end + datetime.timedelta(days=1)
                return Period(start, start + datetime.timedelta(days=self.days - 1))
            months = {"month": 1, "quarter": 3, "year": 12}[kind]
            start = add_months(self._start, months)
            end = add_months(start, months - 1)
            return Period(start, datetime.date(end.year, end.month, last_day(end.year, end.month)))
        except (OverflowError, DateError):
            raise DateError("no period after %s" % self.label) from None

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise DateError("invalid period %r" % (text,))
        try:
            m = re.fullmatch(r"([0-9]{4})", text)
            if m:
                y = int(m.group(1))
                return cls(datetime.date(y, 1, 1), datetime.date(y, 12, 31))
            m = re.fullmatch(r"([0-9]{4})-([0-9]{2})", text)
            if m:
                y, mo = int(m.group(1)), int(m.group(2))
                return cls(datetime.date(y, mo, 1), datetime.date(y, mo, last_day(y, mo)))
            m = re.fullmatch(r"([0-9]{4})-Q([1-4])", text)
            if m:
                y, q = int(m.group(1)), int(m.group(2))
                mo = _QUARTER_START[q]
                return cls(datetime.date(y, mo, 1), datetime.date(y, mo + 2, last_day(y, mo + 2)))
            m = re.fullmatch(r"([0-9]{4}-[0-9]{2}-[0-9]{2})\.\.([0-9]{4}-[0-9]{2}-[0-9]{2})", text)
            if m:
                return cls(parse_date(m.group(1)), parse_date(m.group(2)))
        except (ValueError, DateError):
            pass
        raise DateError("invalid period '%s': expected YYYY, YYYY-MM, YYYY-QN or YYYY-MM-DD..YYYY-MM-DD" % text)


def _period_of(d, step):
    if step == "week":
        start = d - datetime.timedelta(days=d.weekday())
        try:
            end = start + datetime.timedelta(days=6)
        except OverflowError:
            end = datetime.date.max
        return Period(start, end)
    if step == "month":
        return Period(d.replace(day=1), d.replace(day=last_day(d.year, d.month)))
    if step == "quarter":
        mo = (d.month - 1) // 3 * 3 + 1
        return Period(datetime.date(d.year, mo, 1), datetime.date(d.year, mo + 2, last_day(d.year, mo + 2)))
    return Period(datetime.date(d.year, 1, 1), datetime.date(d.year, 12, 31))


def period_containing(d, step):
    """The calendar period of kind `step` (week, month, quarter, year) holding date d."""
    if step not in ("week", "month", "quarter", "year"):
        raise DateError("unknown step %r" % (step,))
    return _period_of(d, step)


def periods(start, end, step):
    if step not in ("week", "month", "quarter", "year"):
        raise DateError("unknown step %s: expected week, month, quarter or year" % _q(step))
    if not _is_date(start) or not _is_date(end):
        raise DateError("periods needs two dates, got %r and %r" % (start, end))
    if end < start:
        raise DateError("end %s is before start %s" % (format_date(end), format_date(start)))
    out = []
    p = _period_of(start, step)
    while True:
        out.append(p)
        if p.end >= end:
            break
        start2 = p.end + datetime.timedelta(days=1)
        p = _period_of(start2, step)
    return out
