    digits = digits.rjust(exp + 1, "0")
    return sign + digits[:-exp] + "." + digits[-exp:]


_AMOUNT_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def parse_amount(text, code):
    exp = currency(code).exponent
    if not isinstance(text, str):
        raise MoneyError("invalid amount %r: expected text" % (text,))
    m = _AMOUNT_RE.fullmatch(text)
    if not m:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.groups()
    if frac is not None:
        if exp == 0:
            raise MoneyError("invalid amount '%s': %s has no decimals" % (text, code))
        if len(frac) > exp:
            raise MoneyError("invalid amount '%s': %s has at most %d decimals" % (text, code, exp))
    frac = (frac or "").ljust(exp, "0")
    value = int(whole) * 10 ** exp + (int(frac) if frac else 0)
