"""Rules that sort transactions into accounts."""

import dataclasses
import datetime
import re
from fractions import Fraction

from tallybook.accounts import valid_any_root_path
from tallybook.currency import currency, is_currency
from tallybook.dates import DateError, parse_date
from tallybook.errors import ParseError

__all__ = ["parse_rules", "RuleSet", "Rule", "RulesError"]


class RulesError(ParseError):
    """A mistake in a rules file; .line is the 1-based line of the first bad rule."""

    def __init__(self, message="", line=None, **detail):
        super().__init__(message, **detail)
        self.line = line


class _Bad(Exception):
    """Internal: a problem on the line being parsed."""


_LINE_SPLIT_RE = re.compile(r"\r\n|\n|\r")
_OP_CHARS = "<>=!~"
_OPS = ("<=", ">=", "!=", "!~", "<", ">", "=", "~")
_SPACE = " \t"
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")

_TEXT_FIELDS = ("payee", "narration")
_ORDER_FIELDS = ("amount", "date")
_TEXT_OPS = ("=", "!=", "~", "!~")
_ORDER_OPS = ("<", "<=", ">", ">=", "=", "!=")
_ACTIONS = ("account", "tag", "narration", "payee", "flag")

# token kinds
_WORD, _STR, _OP = "word", "string", "operator"


def _tokenize(line):
    tokens = []
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in _SPACE:
            i += 1
            continue
        if c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise _Bad("string is never closed")
                ch = line[j]
                if ch == "\\":
                    if j + 1 >= n:
                        raise _Bad("string is never closed")
                    nxt = line[j + 1]
                    if nxt == '"':
                        buf.append('"')
                    else:
                        buf.append(ch + nxt)
                    j += 2
                    continue
                if ch == '"':
                    break
                buf.append(ch)
                j += 1
            tokens.append((_STR, "".join(buf)))
            i = j + 1
            continue
        if c in _OP_CHARS:
            two = line[i:i + 2]
            if two in _OPS:
                tokens.append((_OP, two))
                i += 2
                continue
            if c == "!":
                # a lone "!" is a word (as in "flag !")
                tokens.append((_WORD, "!"))
                i += 1
                continue
            tokens.append((_OP, c))
            i += 1
            continue
        j = i
        while j < n and line[j] not in _SPACE and line[j] != '"' and line[j] not in _OP_CHARS:
            j += 1
        tokens.append((_WORD, line[i:j]))
        i = j
    return tokens


def _show(tok):
    if tok is None:
        return "end of line"
    kind, text = tok
    if kind == _STR:
        return '"%s"' % text
