_OPS = ("<=", ">=", "!=", "!~", "<", ">", "=", "~")
_SPACE = " \t"
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")

_TEXT_FIELDS = ("payee", "narration")
_ORDER_FIELDS = ("amount", "date")
_TEXT_OPS = ("=", "!=", "~", "!~")
_ORDER_OPS = ("<", "<=", ">", ">=", "=", "!=")
_ACTIONS = ("account", "tag", "narration", "payee", "flag")

# token kinds
_WORD, _STR, _OP = "word", "string", "operator"


def _tokenize(line):
    tokens = []
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in _SPACE:
            i += 1
            continue
        if c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise _Bad("string is never closed")
                ch = line[j]
                if ch == "\\":
                    if j + 1 >= n:
                        raise _Bad("string is never closed")
                    nxt = line[j + 1]
                    if nxt == '"':
                        buf.append('"')
                    else:
                        buf.append(ch + nxt)
                    j += 2
                    continue
                if ch == '"':
                    break
                buf.append(ch)
                j += 1
            tokens.append((_STR, "".join(buf)))
            i = j + 1
            continue
        if c in _OP_CHARS:
            two = line[i:i + 2]
            if two in _OPS:
                tokens.append((_OP, two))
                i += 2
                continue
            if c == "!":
                # a lone "!" is a word (as in "flag !")
                tokens.append((_WORD, "!"))
                i += 1
                continue
            tokens.append((_OP, c))
            i += 1
            continue
        j = i
        while j < n and line[j] not in _SPACE and line[j] != '"' and line[j] not in _OP_CHARS:
            j += 1
        tokens.append((_WORD, line[i:j]))
        i = j
    return tokens


def _show(tok):
    if tok is None:
        return "end of line"
    kind, text = tok
    if kind == _STR:
        return '"%s"' % text
    return "'%s'" % text


class _Cond:
    __slots__ = ("field", "op", "value", "code", "regex")

    def __init__(self, field, op, value, code=None, regex=None):
        self.field = field
        self.op = op
        self.value = value
        self.code = code
        self.regex = regex

    def holds(self, fields):
        f = self.field
        if f in _TEXT_FIELDS:
            text = fields.get(f)
            if text is None:
                text = ""
            text = str(text)
            if self.op == "=":
                return text.casefold() == self.value.casefold()
            if self.op == "!=":
                return text.casefold() != self.value.casefold()
            found = self.regex.search(text) is not None
            return found if self.op == "~" else not found
        if f == "amount":
            money = fields.get("amount")
            if money is None:
                return False
            if self.code is not None and money.currency != self.code:
                return False
            left = Fraction(money.minor, 10 ** currency(money.currency).exponent)
        else:
            left = fields.get("date")
            if not isinstance(left, datetime.date):
                return False
            if isinstance(left, datetime.datetime):
                left = left.date()
        right = self.value
        op = self.op
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right
        if op == "=":
            return left == right
        return left != right


class Rule:
    """One rule: conditions (empty for `any`) and actions."""

    def __init__(self, line, conditions, account=None, tags=(), narration=None, payee=None, flag=None,
                 text=""):
        self.line = line
        self.conditions = tuple(conditions)
        self.account = account
        self.tags = tuple(tags)
        self.narration = narration
        self.payee = payee
        self.flag = flag
        self.text = text

    def matches(self, fields):
        return all(c.holds(fields) for c in self.conditions)

    def actions(self):
        out = {}
        if self.account is not None:
            out["account"] = self.account
        if self.tags:
            out["tags"] = list(self.tags)
        if self.narration is not None:
            out["narration"] = self.narration
        if self.payee is not None:
            out["payee"] = self.payee
        if self.flag is not None:
            out["flag"] = self.flag
        return out

    def __repr__(self):
        return "Rule(line=%d, %r)" % (self.line, self.text)


def _parse_condition(tokens, pos):
    """Parse one condition starting at tokens[pos]; returns (cond, new_pos)."""
    tok = tokens[pos] if pos < len(tokens) else None
    if tok is None or tok[0] != _WORD:
        raise _Bad("expected a condition, found %s" % _show(tok))
    field = tok[1]
    if field in ("then", "and"):
        raise _Bad("expected a condition, found %s" % _show(tok))
    if field not in _TEXT_FIELDS and field not in _ORDER_FIELDS:
        raise _Bad("unknown field %s" % _show(tok))
    pos += 1
    tok = tokens[pos] if pos < len(tokens) else None
    if tok is None or tok[0] != _OP:
        raise _Bad("expected an operator after '%s', found %s" % (field, _show(tok)))
    op = tok[1]
    allowed = _TEXT_OPS if field in _TEXT_FIELDS else _ORDER_OPS
    if op not in allowed:
        raise _Bad("operator '%s' does not work with '%s'" % (op, field))
    pos += 1
    tok = tokens[pos] if pos < len(tokens) else None
    if tok is None or (tok[0] == _WORD and tok[1] in ("then", "and")):
        raise _Bad("missing value after '%s %s'" % (field, op))
    if field in _TEXT_FIELDS:
        if tok[0] != _STR:
            raise _Bad("expected a quoted text after '%s %s', found %s" % (field, op, _show(tok)))
        value = tok[1]
        regex = None
        if op in ("~", "!~"):
            try:
                regex = re.compile(value, re.IGNORECASE)
            except (re.error, OverflowError, RecursionError, ValueError) as e:
                raise _Bad('invalid regular expression "%s": %s' % (value, e))
        return _Cond(field, op, value, regex=regex), pos + 1
    if tok[0] != _WORD:
        raise _Bad("expected a %s after '%s %s', found %s" % (
            "number" if field == "amount" else "date", field, op, _show(tok)))
    text = tok[1]
    if field == "amount":
        m = _AMOUNT_RE.fullmatch(text)
        if not m:
            raise _Bad("invalid amount '%s'" % text)
        number, code = m.groups()
        if code:
            if not re.fullmatch(r"[A-Z]{3}", code):
                raise _Bad("invalid amount '%s': the currency code must be three upper-case letters" % text)
            if not is_currency(code):
                raise _Bad("invalid amount '%s': unknown currency %s" % (text, code))
        return _Cond(field, op, Fraction(number), code=code or None), pos + 1
    try:
        value = parse_date(text)
    except DateError:
        raise _Bad("invalid date '%s': expected a real YYYY-MM-DD date" % text)
    return _Cond(field, op, value), pos + 1


def _parse_line(text, lineno):
    tokens = _tokenize(text)
    if not tokens or tokens[0] != (_WORD, "when"):
        raise _Bad("a rule starts with 'when'")
    pos = 1
    conditions = []
    if pos < len(tokens) and tokens[pos] == (_WORD, "any"):
        pos += 1
        tok = tokens[pos] if pos < len(tokens) else None
        if tok != (_WORD, "then"):
            if tok == (_WORD, "and"):
                raise _Bad("'any' cannot be combined with other conditions")
            if tok is None:
                raise _Bad("missing 'then'")
            raise _Bad("expected 'then' after 'any', found %s" % _show(tok))
    else:
        while True:
            cond, pos = _parse_condition(tokens, pos)
            conditions.append(cond)
            tok = tokens[pos] if pos < len(tokens) else None
            if tok == (_WORD, "and"):
                pos += 1
                if pos < len(tokens) and tokens[pos] == (_WORD, "any"):
                    raise _Bad("'any' cannot be combined with other conditions")
                continue
            if tok == (_WORD, "then"):
                break
            if tok is None:
                raise _Bad("missing 'then'")
            raise _Bad("expected 'and' or 'then', found %s" % _show(tok))
    pos += 1  # past "then"
    if pos >= len(tokens):
        raise _Bad("nothing after 'then'")
    account = narration = payee = flag = None
    tags = []
    seen = set()
    while pos < len(tokens):
        tok = tokens[pos]
        if tok[0] != _WORD or tok[1] not in _ACTIONS:
            if tok[0] == _WORD and tok[1].isalpha() and tok[1].islower():
                raise _Bad("unknown action %s" % _show(tok))
            raise _Bad("expected an action, found %s" % _show(tok))
        name = tok[1]
        if name != "tag":
            if name in seen:
                raise _Bad("'%s' given twice" % name)
            seen.add(name)
        pos += 1
        val = tokens[pos] if pos < len(tokens) else None
        if val is None:
            raise _Bad("missing value after '%s'" % name)
        pos += 1
        if name in ("narration", "payee"):
            if val[0] != _STR:
                raise _Bad("expected a quoted text after '%s', found %s" % (name, _show(val)))
            if name == "narration":
                narration = val[1]
            else:
                if not val[1].strip():
                    raise _Bad("the payee cannot be empty")
                payee = val[1]
            continue
        if val[0] != _WORD:
            raise _Bad("expected a value after '%s', found %s" % (name, _show(val)))
        word = val[1]
        if name == "account":
            if not valid_any_root_path(word):
                raise _Bad("invalid account path '%s'" % word)
            account = word
        elif name == "tag":
            if not _TAG_RE.fullmatch(word):
                raise _Bad("invalid tag name '%s'" % word)
            low = word.lower()
            if low not in tags:
                tags.append(low)
        else:
            if word not in ("*", "!"):
                raise _Bad("invalid flag '%s': expected * or !" % word)
            flag = word
    return Rule(lineno, conditions, account=account, tags=tags, narration=narration, payee=payee,
                flag=flag, text=text.strip())


def parse_rules(text):
    """Read a rules file into a RuleSet (RulesError on the first bad rule)."""
    if not isinstance(text, str):
        raise RulesError("rules must be text, got %r" % (text,), line=None)
    if text.startswith("\ufeff"):
        text = text[1:]
    rules = []
    if text == "":
        return RuleSet(rules)
    for lineno, line in enumerate(_LINE_SPLIT_RE.split(text), 1):
        stripped = line.strip(" \t")
        if not stripped or stripped.startswith("#"):
            continue
        try:
            rules.append(_parse_line(line, lineno))
        except _Bad as e:
            raise RulesError("line %d: %s" % (lineno, e), line=lineno) from None
    return RuleSet(rules)


class RuleSet:
    """Rules in file order; the first one whose conditions all hold wins."""

    def __init__(self, rules=()):
        self._rules = list(rules)

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(list(self._rules))

    def __repr__(self):
        return "RuleSet(%d rules)" % len(self._rules)

    def match(self, fields):
        for rule in self._rules:
            if rule.matches(fields):
                return rule
        return None

    def apply(self, fields):
        rule = self.match(fields)
        if rule is None:
            return None
        return rule.actions()

    def categorize(self, tx):
        postings = list(tx.postings or [])
        fields = {
            "payee": tx.payee,
            "narration": tx.narration,
            "date": tx.date,
            "amount": postings[0].amount if postings else None,
        }
        rule = self.match(fields)
        if rule is None:
            return tx
        changes = {"tags": tuple(sorted(set(tx.tags or ()) | set(rule.tags)))}
        if rule.payee is not None:
            changes["payee"] = rule.payee
        if rule.narration is not None:
            changes["narration"] = rule.narration
        if rule.flag is not None:
            changes["flag"] = rule.flag
        if rule.account is not None and len(postings) == 2:
            postings[1] = dataclasses.replace(postings[1], account=rule.account)
        changes["postings"] = postings
        return dataclasses.replace(tx, **changes)

"""Importing bank statements (CSV) through a profile."""

import datetime
import re
from collections import Counter

from tallybook.accounts import valid_any_root_path
from tallybook.currency import currency, is_currency
from tallybook.errors import ParseError
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.rules import RuleSet, parse_rules

__all__ = ["parse_profile", "ImportProfile", "import_csv", "ImportResult", "CsvImportError"]


class CsvImportError(ParseError):
    """A bad profile, or a file that cannot be imported at all."""

    def __init__(self, message="", line=None, **detail):
        super().__init__(message, **detail)
        self.line = line


class _Bad(Exception):
    pass


_LINE_SPLIT_RE = re.compile(r"\r\n|\n|\r")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")
_COLUMN_SETTINGS = ("date_column", "payee_column", "narration_column", "amount_column", "debit_column",
                    "credit_column")
_SETTINGS = _COLUMN_SETTINGS + ("currency", "account", "default_account", "date_format", "delimiter", "skip_rows",
                                "has_header", "negate", "decimal_separator", "thousands_separator", "flag", "tags")
_REQUIRED = ("date_column", "payee_column", "currency", "account")
_BOOLS = {"yes": True, "true": True, "no": False, "false": False}
_DELIMITER_WORDS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'",
              ",": ",", ".": ".", "'": "'", " ": " "}

_MONTHS = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october",
           "november", "december"]
_MONTH_FULL = {name: i for i, name in enumerate(_MONTHS, 1)}
_MONTH_ABBR = {name[:3]: i for i, name in enumerate(_MONTHS, 1)}


class ImportProfile:
    """How one bank lays out its CSV statements."""

    def __init__(self, date_column=None, payee_column=None, narration_column=None, amount_column=None,
                 debit_column=None, credit_column=None, currency=None, account=None, default_account=None,
                 date_format="%Y-%m-%d", delimiter=",", skip_rows=0, has_header=True, negate=False,
                 decimal_separator=".", thousands_separator="", flag="*", tags=()):
        self.date_column = date_column
        self.payee_column = payee_column
        self.narration_column = narration_column
        self.amount_column = amount_column
        self.debit_column = debit_column
        self.credit_column = credit_column
        self.currency = currency
        self.account = account
        self.default_account = default_account
        self.date_format = date_format
        self.delimiter = delimiter
        self.skip_rows = skip_rows
        self.has_header = has_header
        self.negate = negate
        self.decimal_separator = decimal_separator
        self.thousands_separator = thousands_separator
        self.flag = flag
        self.tags = tuple(tags)

    def _items(self):
        return tuple((name, getattr(self, name)) for name in _SETTINGS)

    def __eq__(self, other):
        return isinstance(other, ImportProfile) and self._items() == other._items()

    def __ne__(self, other):
        return not self.__eq__(other)

    def __repr__(self):
        return "ImportProfile(%s)" % ", ".join("%s=%r" % kv for kv in self._items())


# ---------------------------------------------------------------- date formats

def _compile_date_format(fmt):
    """A regex and a list of group kinds for a date format; _Bad when the format is wrong."""
    parts = []
    kinds = []
    i, n = 0, len(fmt)
    while i < n:
        c = fmt[i]
        if c != "%":
            parts.append(re.escape(c))
            i += 1
            continue
        if i + 1 >= n:
            raise _Bad("invalid date_format '%s': a lone %% at the end" % fmt)
        d = fmt[i + 1]
        i += 2
        if d == "%":
            parts.append("%")
        elif d == "Y":
            parts.append("([0-9]{4})")
            kinds.append("Y")
        elif d == "y":
            parts.append("([0-9]{2})")
            kinds.append("y")
        elif d == "m":
            parts.append("([0-9]{1,2})")
            kinds.append("m")
        elif d == "d":
            parts.append("([0-9]{1,2})")
            kinds.append("d")
        elif d == "b":
            parts.append("([A-Za-z]{3})")
            kinds.append("b")
        elif d == "B":
            parts.append("([A-Za-z]+)")
            kinds.append("B")
        else:
            raise _Bad("invalid date_format '%s': unknown directive %%%s" % (fmt, d))
    years = sum(k in "Yy" for k in kinds)
    months = sum(k in "mbB" for k in kinds)
    days = sum(k == "d" for k in kinds)
    if years != 1 or months != 1 or days != 1:
        raise _Bad("invalid date_format '%s': needs a year, a month and a day, each once" % fmt)
    return re.compile("".join(parts)), kinds


def _parse_date_cell(text, fmt, compiled):
    regex, kinds = compiled
    m = regex.fullmatch(text)
    if m:
        year = month = day = None
        for kind, value in zip(kinds, m.groups()):
            if kind == "Y":
                year = int(value)
            elif kind == "y":
                year = 2000 + int(value)
            elif kind == "m":
                month = int(value)
            elif kind == "d":
                day = int(value)
            elif kind == "b":
                month = _MONTH_ABBR.get(value.lower())
            else:
                month = _MONTH_FULL.get(value.lower())
        if month is not None:
            try:
                return datetime.date(year, month, day)
            except ValueError:
                pass
    raise _Bad("invalid date '%s': expected a real date written %s" % (text, fmt))


# ---------------------------------------------------------------- profile

def _check_column(value, has_header):
    if value == "":
        raise _Bad("empty column")
    if value.startswith("#"):
        digits = value[1:]
        if not digits or not digits.isascii() or not digits.isdigit():
            raise _Bad("invalid column '%s': expected #N, a column number from 1" % value)
        if int(digits) == 0:
            raise _Bad("invalid column '%s': columns are counted from 1" % value)
        return value
    if not has_header:
        raise _Bad("invalid column '%s': with has_header = no only #N columns are allowed" % value)
    return value


def _strip_value(raw):
    value = raw.strip(" ")
    if value != "\t":
        value = value.strip(" \t")
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        value = value[1:-1]
    return value


def parse_profile(text):
    """Read a profile text into an ImportProfile (CsvImportError when it is bad)."""
    if not isinstance(text, str):
        raise CsvImportError("a profile must be text, got %r" % (text,))
    if text.startswith("﻿"):
        text = text[1:]
    lines = []
    for lineno, line in enumerate(_LINE_SPLIT_RE.split(text), 1):
        stripped = line.strip(" \t")
        if not stripped or stripped.startswith("#"):
            continue
        lines.append((lineno, line))

    # has_header may come after the columns: look it up first (a bad value is reported on its own line).
    has_header = True
    for lineno, line in lines:
        if "=" in line:
            name, raw = line.split("=", 1)
            if name.strip(" \t") == "has_header":
                v = _BOOLS.get(_strip_value(raw).lower())
                if v is not None:
                    has_header = v
                break

    values = {}
    for lineno, line in lines:
        try:
            if "=" not in line:
                raise _Bad("expected 'setting = value'")
            name, raw = line.split("=", 1)
            name = name.strip(" \t")
            value = _strip_value(raw)
            if name not in _SETTINGS:
                raise _Bad("unknown setting '%s'" % name)
            if name in values:
                raise _Bad("setting '%s' given twice" % name)
            values[name] = _check_setting(name, value, has_header)
        except _Bad as e:
            raise CsvImportError("line %d: %s" % (lineno, e), line=lineno) from None

    for name in _REQUIRED:
        if name not in values:
            raise CsvImportError("missing required setting '%s'" % name)
    has_amount = "amount_column" in values
    has_debit = "debit_column" in values
    has_credit = "credit_column" in values
    if has_amount and (has_debit or has_credit):
        raise CsvImportError("amount_column cannot be used together with debit_column/credit_column")
    if not has_amount:
        if has_debit != has_credit:
            raise CsvImportError("debit_column and credit_column must be given together")
        if not has_debit:
            raise CsvImportError("missing amount_column (or debit_column and credit_column)")
    profile = ImportProfile(**values)
    if profile.decimal_separator == profile.thousands_separator:
        raise CsvImportError("decimal_separator and thousands_separator cannot be the same")
    return profile


def _check_setting(name, value, has_header):
    if name in _COLUMN_SETTINGS:
        return _check_column(value, has_header)
    if name in ("account", "default_account"):
        if not valid_any_root_path(value):
            raise _Bad("invalid account path '%s'" % value)
        return value
    if name == "currency":
        if not is_currency(value):
            raise _Bad("unknown currency '%s'" % value)
        return value
    if name == "date_format":
        _compile_date_format(value)
        return value
    if name == "delimiter":
        if value in _DELIMITER_WORDS:
            return _DELIMITER_WORDS[value]
        if len(value) != 1 or value in '"\r\n':
            raise _Bad("invalid delimiter '%s'" % value)
        return value
    if name == "skip_rows":
        if not value or not value.isascii() or not value.isdigit():
            raise _Bad("invalid skip_rows '%s': expected a whole number" % value)
        return int(value)
    if name in ("has_header", "negate"):
        v = _BOOLS.get(value.lower())
        if v is None:
            raise _Bad("invalid %s '%s': expected yes, no, true or false" % (name, value))
        return v
    if name == "decimal_separator":
        if value not in (".", ","):
            raise _Bad("invalid decimal_separator '%s': expected . or ," % value)
        return value
    if name == "thousands_separator":
        if value not in _THOUSANDS:
            raise _Bad("invalid thousands_separator '%s'" % value)
        return _THOUSANDS[value]
    if name == "flag":
        if value not in ("*", "!"):
            raise _Bad("invalid flag '%s': expected * or !" % value)
        return value
    # tags
    if not value.strip():
        raise _Bad("tags cannot be empty")
    tags = set()
    for part in value.split(","):
        part = part.strip(" \t")
        if not _TAG_RE.fullmatch(part):
            raise _Bad("invalid tag name '%s'" % part)
        tags.add(part.lower())
    return tuple(sorted(tags))


# ---------------------------------------------------------------- reading CSV

def _skip_lines(text, count):
    """Drop `count` lines (any line ending); returns (rest, number of lines dropped)."""
    pos = 0
    dropped = 0
    n = len(text)
    while dropped < count and pos < n:
        m = _LINE_SPLIT_RE.search(text, pos)
        if m is None:
            pos = n
        else:
            pos = m.end()
        dropped += 1
    return text[pos:], dropped


def _read_records(text, delimiter, first_line):
    """Yield (line_number, cells) for every CSV record."""
    records = []
    i, n = 0, len(text)
    line = first_line
    while i < n:
        start = line
        cells = []
        cell = []
        while True:
            # read one field
            if i < n and text[i] == '"':
                i += 1
                while i < n:
                    c = text[i]
                    if c == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            cell.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\n":
                        line += 1
                    cell.append(c)
                    i += 1
            # unquoted part (or what follows a closing quote)
            while i < n and text[i] != delimiter and text[i] != "\n" and not text.startswith("\r\n", i):
                cell.append(text[i])
                i += 1
            cells.append("".join(cell))
