"""Importing bank statements (CSV) through a profile."""

import datetime
import re
from collections import Counter

from tallybook.accounts import valid_any_root_path
from tallybook.currency import currency, is_currency
from tallybook.errors import ParseError
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.rules import RuleSet, parse_rules

__all__ = ["parse_profile", "ImportProfile", "import_csv", "ImportResult", "CsvImportError"]


class CsvImportError(ParseError):
    """A bad profile, or a file that cannot be imported at all."""

    def __init__(self, message="", line=None, **detail):
        super().__init__(message, **detail)
        self.line = line


class _Bad(Exception):
    pass


_LINE_SPLIT_RE = re.compile(r"\r\n|\n|\r")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")
_COLUMN_SETTINGS = ("date_column", "payee_column", "narration_column", "amount_column", "debit_column",
                    "credit_column")
_SETTINGS = _COLUMN_SETTINGS + ("currency", "account", "default_account", "date_format", "delimiter", "skip_rows",
                                "has_header", "negate", "decimal_separator", "thousands_separator", "flag", "tags")
_REQUIRED = ("date_column", "payee_column", "currency", "account")
_BOOLS = {"yes": True, "true": True, "no": False, "false": False}
_DELIMITER_WORDS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'",
              ",": ",", ".": ".", "'": "'", " ": " "}

_MONTHS = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october",
           "november", "december"]
_MONTH_FULL = {name: i for i, name in enumerate(_MONTHS, 1)}
_MONTH_ABBR = {name[:3]: i for i, name in enumerate(_MONTHS, 1)}


class ImportProfile:
    """How one bank lays out its CSV statements."""

    def __init__(self, date_column=None, payee_column=None, narration_column=None, amount_column=None,
                 debit_column=None, credit_column=None, currency=None, account=None, default_account=None,
                 date_format="%Y-%m-%d", delimiter=",", skip_rows=0, has_header=True, negate=False,
                 decimal_separator=".", thousands_separator="", flag="*", tags=()):
        self.date_column = date_column
        self.payee_column = payee_column
        self.narration_column = narration_column
        self.amount_column = amount_column
        self.debit_column = debit_column
        self.credit_column = credit_column
        self.currency = currency
        self.account = account
        self.default_account = default_account
        self.date_format = date_format
        self.delimiter = delimiter
        self.skip_rows = skip_rows
        self.has_header = has_header
        self.negate = negate
        self.decimal_separator = decimal_separator
        self.thousands_separator = thousands_separator
        self.flag = flag
        self.tags = tuple(tags)

    def _items(self):
        return tuple((name, getattr(self, name)) for name in _SETTINGS)

    def __eq__(self, other):
        return isinstance(other, ImportProfile) and self._items() == other._items()

    def __ne__(self, other):
        return not self.__eq__(other)

    def __repr__(self):
        return "ImportProfile(%s)" % ", ".join("%s=%r" % kv for kv in self._items())


# ---------------------------------------------------------------- date formats

def _compile_date_format(fmt):
    """A regex and a list of group kinds for a date format; _Bad when the format is wrong."""
    parts = []
    kinds = []
    i, n = 0, len(fmt)
    while i < n:
        c = fmt[i]
        if c != "%":
            parts.append(re.escape(c))
            i += 1
            continue
        if i + 1 >= n:
            raise _Bad("invalid date_format '%s': a lone %% at the end" % fmt)
        d = fmt[i + 1]
        i += 2
        if d == "%":
            parts.append("%")
        elif d == "Y":
            parts.append("([0-9]{4})")
            kinds.append("Y")
        elif d == "y":
            parts.append("([0-9]{2})")
            kinds.append("y")
        elif d == "m":
            parts.append("([0-9]{1,2})")
            kinds.append("m")
        elif d == "d":
            parts.append("([0-9]{1,2})")
            kinds.append("d")
        elif d == "b":
            parts.append("([A-Za-z]{3})")
            kinds.append("b")
        elif d == "B":
            parts.append("([A-Za-z]+)")
            kinds.append("B")
        else:
            raise _Bad("invalid date_format '%s': unknown directive %%%s" % (fmt, d))
    years = sum(k in "Yy" for k in kinds)
    months = sum(k in "mbB" for k in kinds)
    days = sum(k == "d" for k in kinds)
    if years != 1 or months != 1 or days != 1:
        raise _Bad("invalid date_format '%s': needs a year, a month and a day, each once" % fmt)
    return re.compile("".join(parts)), kinds


def _parse_date_cell(text, fmt, compiled):
    regex, kinds = compiled
    m = regex.fullmatch(text)
    if m:
        year = month = day = None
        for kind, value in zip(kinds, m.groups()):
            if kind == "Y":
                year = int(value)
            elif kind == "y":
                year = 2000 + int(value)
            elif kind == "m":
                month = int(value)
            elif kind == "d":
                day = int(value)
            elif kind == "b":
                month = _MONTH_ABBR.get(value.lower())
            else:
                month = _MONTH_FULL.get(value.lower())
        if month is not None:
            try:
                return datetime.date(year, month, day)
            except ValueError:
                pass
    raise _Bad("invalid date '%s': expected a real date written %s" % (text, fmt))


# ---------------------------------------------------------------- profile

def _check_column(value, has_header):
    if value == "":
        raise _Bad("empty column")
    if value.startswith("#"):
        digits = value[1:]
        if not digits or not digits.isascii() or not digits.isdigit():
            raise _Bad("invalid column '%s': expected #N, a column number from 1" % value)
        if int(digits) == 0:
            raise _Bad("invalid column '%s': columns are counted from 1" % value)
        return value
    if not has_header:
        raise _Bad("invalid column '%s': with has_header = no only #N columns are allowed" % value)
    return value


def _strip_value(raw):
    value = raw.strip(" ")
    if value != "\t":
        value = value.strip(" \t")
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        value = value[1:-1]
    return value


def parse_profile(text):
    """Read a profile text into an ImportProfile (CsvImportError when it is bad)."""
    if not isinstance(text, str):
        raise CsvImportError("a profile must be text, got %r" % (text,))
    if text.startswith("\ufeff"):
        text = text[1:]
    lines = []
    for lineno, line in enumerate(_LINE_SPLIT_RE.split(text), 1):
        stripped = line.strip(" \t")
        if not stripped or stripped.startswith("#"):
            continue
        lines.append((lineno, line))

    # has_header may come after the columns: look it up first (a bad value is reported on its own line).
    has_header = True
    for lineno, line in lines:
        if "=" in line:
            name, raw = line.split("=", 1)
            if name.strip(" \t") == "has_header":
                v = _BOOLS.get(_strip_value(raw).lower())
                if v is not None:
                    has_header = v
                break

    values = {}
    for lineno, line in lines:
        try:
            if "=" not in line:
                raise _Bad("expected 'setting = value'")
            name, raw = line.split("=", 1)
            name = name.strip(" \t")
            value = _strip_value(raw)
            if name not in _SETTINGS:
                raise _Bad("unknown setting '%s'" % name)
            if name in values:
                raise _Bad("setting '%s' given twice" % name)
            values[name] = _check_setting(name, value, has_header)
        except _Bad as e:
            raise CsvImportError("line %d: %s" % (lineno, e), line=lineno) from None

    for name in _REQUIRED:
        if name not in values:
            raise CsvImportError("missing required setting '%s'" % name)
    has_amount = "amount_column" in values
    has_debit = "debit_column" in values
    has_credit = "credit_column" in values
    if has_amount and (has_debit or has_credit):
        raise CsvImportError("amount_column cannot be used together with debit_column/credit_column")
    if not has_amount:
        if has_debit != has_credit:
            raise CsvImportError("debit_column and credit_column must be given together")
        if not has_debit:
            raise CsvImportError("missing amount_column (or debit_column and credit_column)")
    profile = ImportProfile(**values)
    if profile.decimal_separator == profile.thousands_separator:
        raise CsvImportError("decimal_separator and thousands_separator cannot be the same")
    return profile


def _check_setting(name, value, has_header):
    if name in _COLUMN_SETTINGS:
        return _check_column(value, has_header)
    if name in ("account", "default_account"):
        if not valid_any_root_path(value):
            raise _Bad("invalid account path '%s'" % value)
        return value
    if name == "currency":
        if not is_currency(value):
            raise _Bad("unknown currency '%s'" % value)
        return value
    if name == "date_format":
        _compile_date_format(value)
        return value
    if name == "delimiter":
        if value in _DELIMITER_WORDS:
            return _DELIMITER_WORDS[value]
        if len(value) != 1 or value in '"\r\n':
            raise _Bad("invalid delimiter '%s'" % value)
        return value
    if name == "skip_rows":
        if not value or not value.isascii() or not value.isdigit():
            raise _Bad("invalid skip_rows '%s': expected a whole number" % value)
        return int(value)
    if name in ("has_header", "negate"):
        v = _BOOLS.get(value.lower())
        if v is None:
            raise _Bad("invalid %s '%s': expected yes, no, true or false" % (name, value))
        return v
    if name == "decimal_separator":
        if value not in (".", ","):
            raise _Bad("invalid decimal_separator '%s': expected . or ," % value)
        return value
    if name == "thousands_separator":
        if value not in _THOUSANDS:
            raise _Bad("invalid thousands_separator '%s'" % value)
        return _THOUSANDS[value]
    if name == "flag":
        if value not in ("*", "!"):
            raise _Bad("invalid flag '%s': expected * or !" % value)
        return value
    # tags
    if not value.strip():
        raise _Bad("tags cannot be empty")
    tags = set()
    for part in value.split(","):
        part = part.strip(" \t")
        if not _TAG_RE.fullmatch(part):
            raise _Bad("invalid tag name '%s'" % part)
        tags.add(part.lower())
    return tuple(sorted(tags))


# ---------------------------------------------------------------- reading CSV

def _skip_lines(text, count):
    """Drop `count` lines (any line ending); returns (rest, number of lines dropped)."""
    pos = 0
    dropped = 0
    n = len(text)
    while dropped < count and pos < n:
        m = _LINE_SPLIT_RE.search(text, pos)
        if m is None:
            pos = n
        else:
            pos = m.end()
        dropped += 1
    return text[pos:], dropped


def _read_records(text, delimiter, first_line):
    """Yield (line_number, cells) for every CSV record."""
    records = []
    i, n = 0, len(text)
    line = first_line
    while i < n:
        start = line
        cells = []
        cell = []
        while True:
            # read one field
            if i < n and text[i] == '"':
                i += 1
                while i < n:
                    c = text[i]
                    if c == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            cell.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\n":
                        line += 1
                    cell.append(c)
                    i += 1
            # unquoted part (or what follows a closing quote)
            while i < n and text[i] != delimiter and text[i] != "\n" and not text.startswith("\r\n", i):
                cell.append(text[i])
                i += 1
            cells.append("".join(cell))
            cell = []
            if i >= n:
                break
            if text[i] == delimiter:
                i += 1
                if i >= n:
                    cells.append("")
                    break
                continue
            # line end
            i += 2 if text[i] == "\r" else 1
            line += 1
            break
        records.append((start, cells))
    return records


# ---------------------------------------------------------------- amounts

def _amount_regex(decimal, thousands):
    d = re.escape(decimal)
    if thousands:
        t = re.escape(thousands)
        whole = r"(?:[0-9]{1,3}(?:%s[0-9]{3})+|[0-9]+)" % t
    else:
        whole = r"[0-9]+"
    return re.compile(r"(%s)(?:%s([0-9]+))?" % (whole, d))


def _parse_amount_cell(text, profile, regex, exponent):
    """Signed minor units for a cell (already trimmed); _Bad when it is not an amount."""
    if text == "":
        raise _Bad("empty amount")
    body = text
    negative = False
    if len(body) >= 2 and body[0] == "(" and body[-1] == ")":
        body = body[1:-1]
        negative = True
        sign_ok = False
    else:
        sign_ok = True
    if sign_ok and body[:1] in ("+", "-"):
        negative = body[0] == "-"
        body = body[1:]
    m = regex.fullmatch(body)
    if not m:
        raise _Bad("invalid amount '%s'" % text)
    whole, frac = m.groups()
    if profile.thousands_separator:
        whole = whole.replace(profile.thousands_separator, "")
    frac = frac or ""
    if len(frac) > exponent:
        raise _Bad("invalid amount '%s': %s has %s" % (
            text, profile.currency, "no decimals" if exponent == 0 else "at most %d decimals" % exponent))
    value = int(whole) * 10 ** exponent + (int(frac.ljust(exponent, "0")) if exponent else 0)
    return -value if negative else value


# ---------------------------------------------------------------- import

class ImportResult:
    """What an import produced: new transactions, duplicates and bad rows."""

    def __init__(self, transactions=None, duplicates=None, errors=None):
        self.transactions = list(transactions or [])
        self.duplicates = list(duplicates or [])
        self.errors = list(errors or [])

    def __repr__(self):
        return "ImportResult(%d transactions, %d duplicates, %d errors)" % (
            len(self.transactions), len(self.duplicates), len(self.errors))


def _clean(text):
    return " ".join(text.split())


def _key(tx, account):
    for p in tx.postings or ():
        if p.account == account:
            return (tx.date, p.amount, tx.payee)
    return None


def import_csv(text, profile, rules=None, existing=()):
    """Turn a CSV statement into transactions (see ImportResult)."""
    if isinstance(profile, str):
        profile = parse_profile(profile)
    if not isinstance(profile, ImportProfile):
        raise CsvImportError("profile must be an ImportProfile or profile text, got %r" % (profile,))
    if isinstance(rules, str):
        rules = parse_rules(rules)
    if rules is not None and not isinstance(rules, RuleSet):
        raise CsvImportError("rules must be a RuleSet, rules text or None, got %r" % (rules,))
    if not isinstance(text, str):
        raise CsvImportError("the CSV file must be text, got %r" % (text,))
    if text.startswith("\ufeff"):
        text = text[1:]

    rest, dropped = _skip_lines(text, profile.skip_rows)
    records = _read_records(rest, profile.delimiter, dropped + 1)
    records = [(ln, cells) for ln, cells in records if any(c.strip() for c in cells)]

    # resolve columns to 0-based indexes
    columns = {}
    names = [n for n in _COLUMN_SETTINGS if getattr(profile, n) is not None]
    if profile.has_header:
        if not records:
            raise CsvImportError("the file has no header")
        header = [c.strip().casefold() for c in records[0][1]]
        records = records[1:]
    for name in names:
        spec = getattr(profile, name)
        if spec.startswith("#") and spec[1:].isdigit():
            columns[name] = int(spec[1:]) - 1
            continue
        if not profile.has_header:
            raise CsvImportError("column '%s' needs a header: use #N with has_header = no" % spec)
        want = spec.strip().casefold()
        if want not in header:
            raise CsvImportError("column '%s' is not in the header" % spec)
        columns[name] = header.index(want)

    fmt = profile.date_format
    compiled = _compile_date_format(fmt)
    exponent = currency(profile.currency).exponent
    amount_re = _amount_regex(profile.decimal_separator, profile.thousands_separator)

    built = []  # (row, tx)
    errors = []
    for row, cells in records:
        try:
            def cell(name):
                idx = columns[name]
                if idx >= len(cells):
                    raise _Bad("row has no column '%s'" % getattr(profile, name))
                return cells[idx]

            date_text = cell("date_column").strip()
            payee_text = cell("payee_column")
            if profile.amount_column is not None:
                amount_cells = [cell("amount_column")]
            else:
                amount_cells = [cell("debit_column"), cell("credit_column")]
            narration = ""
            if "narration_column" in columns and columns["narration_column"] < len(cells):
                narration = _clean(cells[columns["narration_column"]])

            on = _parse_date_cell(date_text, fmt, compiled)
            payee = _clean(payee_text)
            if not payee:
                raise _Bad("empty payee")
            if profile.amount_column is not None:
                minor = _parse_amount_cell(amount_cells[0].strip(), profile, amount_re, exponent)
            else:
                debit, credit = (c.strip() for c in amount_cells)
                if debit and credit:
                    raise _Bad("both debit '%s' and credit '%s' are filled" % (debit, credit))
                if not debit and not credit:
                    raise _Bad("neither debit nor credit is filled")
                if credit:
                    minor = _parse_amount_cell(credit, profile, amount_re, exponent)
                else:
                    minor = -_parse_amount_cell(debit, profile, amount_re, exponent)
            if profile.negate:
                minor = -minor
            if minor == 0:
                raise _Bad("amount is zero")
            amount = Money(minor, profile.currency)

            counter = None
            flag = profile.flag
            tags = set(profile.tags)
            if rules is not None:
                rule = rules.match({"payee": payee, "narration": narration, "date": on, "amount": amount})
                if rule is not None:
                    counter = rule.account
                    if rule.payee is not None:
                        payee = rule.payee
                    if rule.narration is not None:
                        narration = rule.narration
                    if rule.flag is not None:
                        flag = rule.flag
                    tags.update(rule.tags)
            if counter is None:
                counter = profile.default_account
            if counter is None:
                raise _Bad("no account for the other side: no rule picks one and there is no default_account")
            tx = Transaction(
                date=on,
                payee=payee,
                narration=narration,
                postings=[Posting(profile.account, amount), Posting(counter, -amount)],
                tags=tuple(sorted(tags)),
                flag=flag,
                id=None,
            )
            built.append(tx)
        except _Bad as e:
            errors.append((row, str(e)))

    have = Counter()
    for tx in existing or ():
        k = _key(tx, profile.account)
        if k is not None:
            have[k] += 1
    seen = Counter()
    result = ImportResult(errors=errors)
    for tx in built:
        k = _key(tx, profile.account)
        seen[k] += 1
        if seen[k] <= have[k]:
            result.duplicates.append(tx)
        else:
            result.transactions.append(tx)
    return result
